function proRoleIcon(role: string) {
  const r = (role || '').toLowerCase();
  const common = { viewBox: '0 0 24 24', strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const };
  if (/architect|engineer|design/.test(r)) return <svg {...common}><circle cx="12" cy="12" r="9"/><polygon points="16.5 7.5 13.7 13.7 7.5 16.5 10.3 10.3"/></svg>;
  if (/general/.test(r)) return <svg {...common}><path d="M2 18a1 1 0 0 0 1 1h18a1 1 0 0 0 1-1v-2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1z"/><path d="M10 10V5a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1v5"/><path d="M4 15v-3a6 6 0 0 1 6-6"/><path d="M14 6a6 6 0 0 1 6 6v3"/></svg>;
  if (/electric/.test(r)) return <svg {...common}><path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z"/></svg>;
  if (/mason/.test(r)) return <svg {...common}><rect x="3" y="4" width="18" height="16" rx="1"/><path d="M3 9.3h18"/><path d="M3 14.6h18"/><path d="M9 4v5.3"/><path d="M15 9.3v5.3"/><path d="M9 14.6V20"/></svg>;
  if (/sign/.test(r)) return <svg {...common}><rect x="3" y="4" width="18" height="10" rx="1.5"/><path d="M12 14v6"/><path d="M8 20h8"/><path d="M7 9h10"/></svg>;
  if (/expedit/.test(r)) return <svg {...common}><rect x="4" y="4" width="16" height="18" rx="2"/><path d="M9 2h6a1 1 0 0 1 1 1v2H8V3a1 1 0 0 1 1-1z"/><path d="M8.5 12h7"/><path d="M8.5 16h4.5"/></svg>;
  if (/plumb/.test(r)) return <svg {...common}><path d="M12 2.7S6 9 6 14a6 6 0 0 0 12 0c0-5-6-11.3-6-11.3z"/></svg>;
  return <svg {...common}><path d="M14.7 6.3a4 4 0 0 0-5.4 5.4L3 18v3h3l6.3-6.3a4 4 0 0 0 5.4-5.4l-2.7 2.7-2-2 2.7-2.7z"/></svg>;
}


function formatNumberWithCommas(value: string): string {
  // Remove non-numeric chars except decimal point
  const numericValue = value.replace(/[^\d.]/g, '');
  if (!numericValue) return '';

  // Split on decimal if present
  const parts = numericValue.split('.');
  // Add commas to integer part
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return parts.join('.');
}

// Helper to parse comma-formatted string to number
function parseFormattedNumber(value: string): number {
  return parseFloat(value.replace(/,/g, '')) || 0;
}

function zoningHistoryDateLabel(value: unknown): string | null {
  if (!value) return null;
  const date = new Date(`${String(value).slice(0, 10)}T12:00:00`);
  return Number.isNaN(date.getTime())
    ? null
    : date.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
}

function zoningHistoryDate(value: unknown, short = false): string {
  if (!value) return 'Not in the record';
  const date = new Date(`${String(value).slice(0, 10)}T12:00:00`);
  if (Number.isNaN(date.getTime())) return 'Not in the record';
  return date.toLocaleDateString('en-US', short
    ? { month: 'short', day: 'numeric', year: 'numeric' }
    : { month: 'long', day: 'numeric', year: 'numeric' });
}

function normalizedZoningAddress(value: string | undefined | null): string {
  return String(value || '')
    .toUpperCase()
    .replace(/\b(NORTH)\b/g, 'N')
    .replace(/\b(SOUTH)\b/g, 'S')
    .replace(/\b(EAST)\b/g, 'E')
    .replace(/\b(WEST)\b/g, 'W')
    .replace(/\b(AVENUE|AVE|STREET|ST|ROAD|RD|BOULEVARD|BLVD|DRIVE|DR|PLACE|PL|COURT|CT|LANE|LN|WAY|PARKWAY|PKWY)\.?\b/g, '')
    .replace(/[^A-Z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function parseZoningNumber(value: string): number | null {
  const words: Record<string, number> = {
    one: 1, two: 2, three: 3, four: 4, five: 5,
    six: 6, seven: 7, eight: 8, nine: 9, ten: 10,
  };
  const normalized = value.toLowerCase().trim();
  if (words[normalized] != null) return words[normalized];
  const number = Number(normalized);
  return Number.isFinite(number) && number > 0 ? number : null;
}

function parseBoardUnitEvidence(description: string | null | undefined): {
  count: number | null;
  breakdown: { front?: number; rear?: number } | null;
} {
  const text = String(description || '');
  const matches = Array.from(text.matchAll(/\b(one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+dwelling\s+units?\b/gi));
  if (!matches.length) return { count: null, breakdown: null };
  const counts = matches
    .map((match) => parseZoningNumber(match[1]))
    .filter((count): count is number => count != null);
  if (!counts.length) return { count: null, breakdown: null };
  const breakdown: { front?: number; rear?: number } = {};
  for (const match of matches) {
    const count = parseZoningNumber(match[1]);
    if (count == null || match.index == null) continue;
    const context = text.slice(Math.max(0, match.index - 80), match.index + match[0].length + 100);
    if (/\bfront\b/i.test(context) && breakdown.front == null) breakdown.front = count;
    else if (/\brear\b/i.test(context) && breakdown.rear == null) breakdown.rear = count;
  }
  return {
    count: counts.reduce((sum, count) => sum + count, 0),
    breakdown: breakdown.front != null || breakdown.rear != null ? breakdown : null,
  };
}

function buildZoningHistoryView(
  items: any[] | undefined,
  currentZone: string | null | undefined,
  subjectAddress: string | undefined,
  coverage?: any,
) {
  const rawItems = Array.isArray(items) ? items : [];
  const councilItems = rawItems.filter((item) => item.type === 'legistar');
  const zbaItems = rawItems.filter((item) => item.type === 'zba');
  const priority: Record<string, number> = { Approved: 4, Denied: 4, Withdrawn: 3, Continued: 1, Recorded: 2 };
  const zbaByCase = new Map<string, any[]>();
  for (const item of zbaItems) {
    const key = `${item.ordinanceId || item.title}|${normalizedZoningAddress(item.matchedAddress)}`;
    zbaByCase.set(key, [...(zbaByCase.get(key) || []), item]);
  }
  const caseRows = Array.from(zbaByCase.values()).map((hearings) => {
    const ordered = [...hearings].sort((a, b) =>
      ((priority[b.decision] || 0) - (priority[a.decision] || 0))
      || String(b.date || '').localeCompare(String(a.date || '')),
    );
    const final = { ...ordered[0] };
    const prior = hearings
      .filter((item) => item !== ordered[0] && item.date)
      .sort((a, b) => String(a.date).localeCompare(String(b.date)));
    final.hearingDates = prior.map((item) => item.date);
    return final;
  });
  const rows = [...councilItems, ...caseRows].sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
  const isMapAmendment = (item: any) =>
    !!(item.fromZone || item.toZone || /reclassif|map amendment|rezon/i.test(item.title || ''));
  const isEnacted = (item: any) =>
    !!item.passedDate && !/\b(withdrawn|failed|denied|not passed|tabled)\b/i.test(String(item.status || ''));
  // A Council filing records an application, not an actual district change,
  // until the City record supplies a passage date.
  const rezoning = councilItems.find((item) => isMapAmendment(item) && isEnacted(item));
  // A description can be copied across a continuation, denial, or withdrawal.
  // Only a final approved case can support wording about what the Board ordered.
  const boardConfiguration = caseRows.find((item) =>
    item.decision === 'Approved'
    && /front building.*rear building/i.test(item.description || ''),
  );
  const boardUnitEvidence = parseBoardUnitEvidence(boardConfiguration?.description);
  const developmentAddress = rezoning?.developmentAddress;
  const developmentElsewhere = !!developmentAddress
    && normalizedZoningAddress(developmentAddress) !== normalizedZoningAddress(subjectAddress);
  const subjectYear = Number(String(boardConfiguration?.date || rezoning?.passedDate || rezoning?.date || '').slice(0, 4));
  const yearsAgo = subjectYear ? Math.max(0, new Date().getFullYear() - subjectYear) : null;
  const approvedCase = caseRows.find((item) => item.decision === 'Approved' || item.decision === 'Denied');
  const coverageIsBounded = coverage?.cityCouncil?.complete !== true || coverage?.zba?.checked !== true;
  let takeaway = coverageIsBounded
    ? 'No confirmed zoning action found in the checked record — archive coverage is partial.'
    : currentZone
      ? `No rezoning or ZBA case on record — ${currentZone} since the 2004 code rewrite.`
      : 'No rezoning or ZBA case on record.';
  if (boardConfiguration) {
    takeaway = boardUnitEvidence.count != null
      ? `Subdivided in ${String(boardConfiguration.date).slice(0, 4)} — the Board's order kept ${boardUnitEvidence.count} dwelling units across the front and rear buildings.`
      : `Subdivided in ${String(boardConfiguration.date).slice(0, 4)} — the Board's order addressed the existing front and rear buildings.`;
  } else if (developmentElsewhere && rezoning) {
    takeaway = `Split from ${developmentAddress}’s zoning lot in ${String(rezoning.passedDate || rezoning.date).slice(0, 4)} — the filing names development on the other parcel.`;
  } else if (rezoning?.toZone) {
    takeaway = `Rezoned to ${rezoning.toZone} in ${String(rezoning.passedDate || rezoning.date).slice(0, 4)}${yearsAgo != null ? ` — ${yearsAgo} years ago.` : '.'}`;
  } else if (approvedCase) {
    takeaway = `${approvedCase.decision} at the Zoning Board — ${approvedCase.ordinanceId || 'recorded case'} in ${String(approvedCase.date).slice(0, 4)}.`;
  }

  const matterGroups = new Map<string, { key: string; rows: any[] }>();
  const groupForKey = (key: string) => {
    if (!matterGroups.has(key)) matterGroups.set(key, { key, rows: [] });
    return matterGroups.get(key)!;
  };
  // Final ZBA decisions on the same date share a hearing track. Council actions
  // remain independent unless the source data eventually supplies a durable
  // cross-record identifier; temporal proximity is not evidence of one matter.
  for (const item of caseRows) {
    const date = String(item.date || '').slice(0, 10) || 'undated';
    groupForKey(`zba:${date}`).rows.push(item);
  }
  for (let index = 0; index < councilItems.length; index++) {
    const item = councilItems[index];
    groupForKey(`council:${item.ordinanceId || item.id || index}`).rows.push(item);
  }
  const matters = Array.from(matterGroups.values())
    .map((matter) => {
      const orderedRows = [...matter.rows].sort((a, b) =>
        String(a.passedDate || a.date || '').localeCompare(String(b.passedDate || b.date || '')),
      );
      const text = orderedRows.map((item) => `${item.description || ''} ${item.title || ''}`).join(' ');
      const label = /subdivid|lot split|two zoning lots|divide the lot/i.test(text)
        ? 'the subdivision'
        : /lot area per dwelling unit/i.test(text) && /setback|parking/i.test(text)
          ? 'the new building'
          : null;
      const decidedDate = orderedRows
        .map((item) => String(item.passedDate || item.date || '').slice(0, 10))
        .filter(Boolean)
        .sort()
        .pop() || null;
      return {
        key: matter.key,
        label,
        track: `${orderedRows.length} action${orderedRows.length === 1 ? '' : 's'}${decidedDate ? ` · decided ${zoningHistoryDate(decidedDate, true)}` : ''}`,
        rows: orderedRows,
      };
    })
    .sort((a, b) => {
      const dateA = a.rows.map((item) => String(item.passedDate || item.date || '')).filter(Boolean).sort()[0] || '';
      const dateB = b.rows.map((item) => String(item.passedDate || item.date || '')).filter(Boolean).sort()[0] || '';
      return dateA.localeCompare(dateB);
    });

  return {
    rawItems,
    rows,
    matters,
    caseRows,
    rawHearingCount: zbaItems.length,
    actionCount: councilItems.length + caseRows.length,
    councilItems,
    zbaItems,
    rezoning,
    hasUnenactedMapFiling: councilItems.some((item) => isMapAmendment(item) && !isEnacted(item)),
    boardConfiguration,
    developmentAddress,
    developmentElsewhere,
    boardUnitCount: boardUnitEvidence.count,
    boardUnitBreakdown: boardUnitEvidence.breakdown,
    takeaway,
  };
}

function zoningCouncilActionLabel(item: any): string {
  if (item.fromZone || item.toZone || /reclassif|map amendment|rezon/i.test(item.title || '')) {
    return 'City Council map amendment';
  }
  return item.actionType ? `City Council ${String(item.actionType).toLowerCase()}` : 'City Council zoning action';
}

function zoningHistoryCoverageText(coverage: any): string | null {
  if (!coverage) return null;
  const city = coverage.cityCouncil?.note;
  const zba = coverage.zba?.note;
  const parts = [city ? `City Council: ${city}` : null, zba ? `ZBA: ${zba}` : null].filter(Boolean);
  return parts.length ? parts.join(' ') : null;
}

