function getCookCountyClassLabel(propertyClass: string | null | undefined): string {
  if (!propertyClass) return '';
  const desc = COOK_COUNTY_CLASS_DESCRIPTIONS[propertyClass];
  return desc ? `Class ${propertyClass}: ${desc}` : `Class ${propertyClass}`;
}

function LocationFactCard({ label, value, icon: Icon, loading = false, highlight = false }: any) {
  return (
    <Card className={`border border-border ${highlight ? 'border-foreground' : ''}`}>
      <CardContent className="p-4 flex flex-col h-full justify-between">
        <div className="flex items-center gap-2 text-muted-foreground mb-2">
          <Icon className="w-4 h-4" />
          <span className="font-jbmono text-xs font-bold uppercase tracking-wider">{label}</span>
        </div>
        {loading ? (
          <Skeleton className="h-8 w-3/4" />
        ) : (
          <div className="font-jbmono font-bold text-lg md:text-xl truncate" title={value || "N/A"}>
            {value || "N/A"}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function ValuationMetricBridge({
  runId,
  metric,
  onMetric,
}: {
  runId: number | null;
  metric: string | undefined;
  onMetric: (runId: number | null, metric: string | undefined) => void;
}) {
  useEffect(() => {
    onMetric(runId, metric);
    return () => onMetric(runId, undefined);
  }, [runId, metric, onMetric]);
  return null;
}

