// ── Insight-report print injection ──────────────────────────────────────────
// The insight report is a standalone HTML document with its own global CSS
// (*, body, :root, @page). To print it inside this page without clobbering the
// app's styles, every selector is scoped under #insight-print-root.
function scopeInsightCss(raw: string): string {
  let css = raw
    // drop @media print blocks (they only restyle the standalone body)
    .replace(/@media[^{]*\{(?:[^{}]*\{[^{}]*\})*[^{}]*\}/g, '')
    // drop @page — the app's own @page rules govern the combined print
    .replace(/@page\s*\{[^}]*\}/g, '');
  return css.replace(/(^|\})([^{}@]+)\{/g, (_m, brace, selList) => {
    const scoped = selList
      .split(',')
      .map((s: string) => {
        const sel = s.trim();
        if (!sel) return '';
        if (sel === ':root' || sel === 'body' || sel === 'html') return '#insight-print-root';
        if (sel === '*') return '#insight-print-root *';
        return `#insight-print-root ${sel}`;
      })
      .filter(Boolean)
      .join(',');
    return `${brace}\n${scoped}{`;
  });
}

// Print-time overrides: the report's fixed 816×1056px pages must reflow to the
// app's printable width instead of overflowing the 0.6in page margins.
const INSIGHT_PRINT_OVERRIDES = `
#insight-print-root { display: none; }
@media print {
  #insight-print-root { display: block !important; background: #fff !important; }
  #insight-print-root .page {
    width: 100% !important;
    height: auto !important;
    min-height: 0 !important;
    overflow: visible !important;
    padding: 0 0 10pt 0 !important;
    page-break-after: always;
  }
}`;

// Builds and prepends a hidden, print-only container holding the insight
// report. Returns the element so the caller can remove it after printing.
function injectInsightForPrint(insightHtml: string): HTMLElement {
  // Idempotency: never allow two injected roots (e.g. after an aborted print)
  document.getElementById('insight-print-root')?.remove();

  const doc = new DOMParser().parseFromString(insightHtml, 'text/html');
  // Sanitize: the HTML is generated by our own server template, but defend the
  // DOM boundary anyway — strip active content and event handlers.
  doc.querySelectorAll('script, iframe, object, embed, form, link, meta').forEach(s => s.remove());
  doc.body.querySelectorAll('*').forEach(el => {
    for (const attr of Array.from(el.attributes)) {
      const n = attr.name.toLowerCase();
      const v = attr.value.trim().toLowerCase();
      if (n.startsWith('on')) el.removeAttribute(attr.name);
      else if ((n === 'href' || n === 'src' || n === 'xlink:href') && (v.startsWith('javascript:') || v.startsWith('data:text/html'))) {
        el.removeAttribute(attr.name);
      }
    }
  });
  const css = Array.from(doc.querySelectorAll('style')).map(s => s.textContent || '').join('\n');

  // The report uses Instrument Serif, which the app itself doesn't load
  if (!document.querySelector('link[href*="Instrument+Serif"]')) {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = 'https://fonts.googleapis.com/css2?family=Instrument+Serif&display=swap';
    document.head.appendChild(link);
  }

  const root = document.createElement('div');
  root.id = 'insight-print-root';
  const styleEl = document.createElement('style');
  styleEl.textContent = scopeInsightCss(css) + INSIGHT_PRINT_OVERRIDES;
  root.appendChild(styleEl);
  const content = document.createElement('div');
  content.innerHTML = doc.body.innerHTML;
  root.appendChild(content);
  document.body.prepend(root);
  return root;
}

