  const isInvestSwSectionOpen = sectionStates.investSw;
  const setIsInvestSwSectionOpen = useCallback((v: boolean) => setSectionOpen('investSw', v), [setSectionOpen]);
  const isClass6bSectionOpen = sectionStates.class6b;
  const setIsClass6bSectionOpen = useCallback((v: boolean) => setSectionOpen('class6b', v), [setSectionOpen]);
  const isClass7SectionOpen = sectionStates.class7;
  const setIsClass7SectionOpen = useCallback((v: boolean) => setSectionOpen('class7', v), [setSectionOpen]);
  const isCdgSectionOpen = sectionStates.cdg;
  const setIsCdgSectionOpen = useCallback((v: boolean) => setSectionOpen('cdg', v), [setSectionOpen]);
  const isHubzoneSectionOpen = sectionStates.hubzone;
  const setIsHubzoneSectionOpen = useCallback((v: boolean) => setSectionOpen('hubzone', v), [setSectionOpen]);
  const isQctSectionOpen = sectionStates.qct;
  const setIsQctSectionOpen = useCallback((v: boolean) => setSectionOpen('qct', v), [setSectionOpen]);
  const isChaOpportunitySectionOpen = sectionStates.chaOpportunity;
  const setIsChaOpportunitySectionOpen = useCallback((v: boolean) => setSectionOpen('chaOpportunity', v), [setSectionOpen]);
  const isAduSectionOpen = sectionStates.adu;
  const setIsAduSectionOpen = useCallback((v: boolean) => setSectionOpen('adu', v), [setSectionOpen]);
